CREATE OR REPLACE FUNCTION check_premature_resolution()
RETURNS TRIGGER AS $ 
BEGIN 
    IF NEW.resstat = 'Resolved' THEN 
        -- Assuming there is a column named 'iii_score' in the enforcementactions table
        IF NEW.iii_score > 75.0 THEN 
            RAISE EXCEPTION 'Premature Resolution Block: Investigation Intensity Index score is above threshold'; 
        END IF; 
    END IF; 
    RETURN NEW; 
END; 
$ LANGUAGE plpgsql;

CREATE TRIGGER resolution_check
BEFORE UPDATE ON enforcementactions
FOR EACH ROW
EXECUTE FUNCTION check_premature_resolution();

